class Moon:
    pos: Vector
    vel: Vector = Vector(0, 0, 0)
    def gravitate(self, other: Moon):
        gravitational_force = (other.pos - self.pos).sign()
        self.vel += gravitational_force
        other.vel -= gravitational_force
    def move(self):
        self.pos += self.vel
    def get_energy(self):
        p = 1
        for i in self.vel:
            p *= i
        return p

